<?php
declare(strict_types=1);
namespace CetechDeliveryEngine\Tests\Unit\CustomerPolicy;
use PHPUnit\Framework\TestCase;
final class CustomerPolicyCompositionTest extends TestCase {
 private function probe(string$case):array{$path=dirname(__DIR__,2).'/Support/CustomerPolicy/customer-policy-composition-probe.php';exec(escapeshellarg(PHP_BINARY).' '.escapeshellarg($path).' '.escapeshellarg($case),$lines,$status);self::assertSame(0,$status,implode("\n",$lines));return json_decode(implode("\n",$lines),true,32,JSON_THROW_ON_ERROR);}
 private function inert(array$r):void{foreach($r['touches']as$key=>$count)self::assertSame(0,$count,$key);}
 public function test_all_fifteen_actual_bindings_are_lazy_and_singleton_without_sql_current_or_session_effects():void{$r=$this->probe('lazy');self::assertCount(15,$r['resolved']);foreach($r['resolved']as$expected=>$actual)self::assertSame($expected,$actual);$this->inert($r);}
 public function test_actual_mount_and_off_callbacks_are_inert_before_any_native_session():void{$r=$this->probe('off-mount');self::assertSame(['enabled'=>false,'options'=>[],'cart'=>[]],$r['result']);$this->inert($r);self::assertContains('woocommerce_available_payment_gateways',$r['hooks']);self::assertContains('woocommerce_email_after_order_table',$r['hooks']);self::assertContains('woocommerce_review_order_after_cart_contents',$r['hooks']);}
 public function test_actual_composite_preserves_ordinary_legacy_fingerprint_route_revision_and_delegation():void{$r=$this->probe('ordinary');self::assertSame([str_repeat('a',64),true,true,true],$r['result']);self::assertSame(['fingerprint',['validate','classic'],['complete','classic',7],['admitted','classic',7]],$r['legacy_calls']);$this->inert($r);}
 public function test_default_off_preservation_guard_leaves_absent_ordinary_history_and_legacy_builder_untouched():void{$r=$this->probe('preserve-none');self::assertFalse($r['result']['refused']);$this->inert($r);}
 public function test_future_and_partial_attempted_history_refuse_before_any_legacy_builder_or_repair():void{foreach(['preserve-future','preserve-partial']as$case){$r=$this->probe($case);self::assertTrue($r['result']['refused']);$this->inert($r);}}
 public function test_actual_saved_audience_denial_never_opens_history_sql_or_current_source():void{$r=$this->probe('denied-saved');self::assertSame('',$r['html']);$this->inert($r);}
 private function history(string$backend,string$case):array{$path=dirname(__DIR__,2).'/Support/CustomerPolicy/customer-policy-composition-history-probe.php';exec(escapeshellarg(PHP_BINARY).' '.escapeshellarg($path).' '.escapeshellarg($backend).' '.escapeshellarg($case),$lines,$status);self::assertSame(0,$status,implode("\n",$lines));return json_decode(implode("\n",$lines),true,32,JSON_THROW_ON_ERROR);}
 public function test_complete_native_history_on_both_backends_survives_actual_flag_off_preserver_facade_and_customer_surfaces():void{foreach(['hpos','cpt']as$backend){$r=$this->history($backend,'complete');self::assertFalse($r['new_flag']);self::assertFalse($r['refused']);self::assertTrue($r['preserved']);self::assertStringContainsString('Supplied title',$r['html']);self::assertStringContainsString('&lt;em&gt;text&lt;/em&gt;',$r['html']);self::assertSame($r['html'],$r['email_html']);self::assertStringContainsString('Literal <em>text</em>.',$r['plain']);self::assertStringNotContainsString('PRIVATE',$r['html']);foreach(['scope_calls','wc_calls','legacy_writes','native_writes','getters_in_sql']as$key)self::assertSame(0,$r[$key],$key);self::assertGreaterThanOrEqual(4,$r['owners']);self::assertSame($r['owners'],$r['rollbacks']);self::assertSame($r['owners'],$r['retirements']);}}
 public function test_actual_partial_or_future_native_history_is_not_repaired_or_rendered_with_writer_off():void{foreach(['hpos','cpt']as$backend)foreach(['partial','future']as$case){$r=$this->history($backend,$case);self::assertTrue($r['refused']);self::assertTrue($r['preserved']);self::assertSame('',$r['html']);self::assertSame('',$r['email_html']);self::assertSame('',$r['plain']);foreach(['scope_calls','wc_calls','legacy_writes','native_writes','getters_in_sql']as$key)self::assertSame(0,$r[$key],$key);}}

 public function test_marker_only_partial_is_owned_but_unreadable_and_unpayable_without_writer_or_current_source():void{foreach(['hpos','cpt']as$backend){$r=$this->history($backend,'attempt-only');self::assertFalse($r['new_flag']);self::assertTrue($r['attempted']);self::assertTrue($r['owned']);self::assertFalse($r['order_pay']);self::assertTrue($r['refused']);self::assertTrue($r['preserved']);foreach(['html','email_html','plain']as$key)self::assertSame('',$r[$key],$key);foreach(['scope_calls','wc_calls','legacy_writes','native_writes','getters_in_sql']as$key)self::assertSame(0,$r[$key],$key);}}

}
